def _blank_regex_literals(text: str) -> str:
    """将正则字面量内容替换为空格（定界符 / 与 flags 保留以维持行号/列号），
    避免 /eval\\(/.test 之类的合法模式被 EVAL_RE 误报。"""
    out = list(text)
    for m in JS_REGEX_LITERAL_RE.finditer(text):
        s, e = m.span()
        body_start = s + 1
        body_end = e
        # 仅清空 body 与可能的 flags；首尾 / 保留
        for k in range(body_start, body_end):
            ch = out[k]
            if ch != "\n":
                out[k] = " "
    return "".join(out)

def scan_text(text: str) -> list[str]:
    cleaned = strip_comments_and_strings(_blank_regex_literals(text))
    hits = []
