pub(crate) fn escape_for_log(s: &str, max: usize) -> String {
    // 单遍：剩余预算 + 上一字符 lookahead，避免 `s.replace(...)` 的 O(n) 临时分配
    // 与额外的 `chars().count()` 二次扫描。表格 `|` 列保护改由 "`|" 立即倍增达成。
    let mut escaped = String::with_capacity(s.len());
    let mut budget = max;
    let mut prev = '\0';
    for ch in s.chars() {
        if budget == 0 {
            break;
        }
        let pair_doubled = prev == '|' && ch == ' ';
        match ch {
            '|' if !pair_doubled => {
                escaped.push_str("||");
                budget = budget.saturating_sub(2);
            }
            '\n' => { escaped.push_str("\\n"); budget -= 1; }
            '\r' => { escaped.push_str("\\r"); budget -= 1; }
            '\u{2028}' => { escaped.push_str("\\u{2028}"); budget -= 1; }
            '\u{2029}' => { escaped.push_str("\\u{2029}"); budget -= 1; }
            c if c.is_control() => { let s = c.escape_default().to_string(); budget = budget.saturating_sub(s.chars().count()); escaped.push_str(&s); }
            c => { escaped.push(c); budget -= 1; }
        }
        prev = ch;
    }
    if escaped.chars().count() > max {
        let mut out: String = escaped.chars().take(max).collect();
        out.push('…');
        out
    } else {
        escaped
    }
}

