/// get_password 结果分类——区分 NoEntry（未配置）与真实故障：
/// codex/plaintext 端对未配置与 keychain 锁定产生两种 code，
/// 前端可按 code 精准提示。
pub(crate) fn classify_get_password(r: Result<String, keyring::Error>) -> CommandResult<String> {
    match r {
        Ok(s) if !s.trim().is_empty() => Ok(s),
        Ok(_) => Err(CommandError::KeyringNoEntry), // 空值视同未配置
        Err(keyring::Error::NoEntry) => Err(CommandError::KeyringNoEntry),
        Err(e) => Err(CommandError::KeyringError(format!("读取 API Key 失败：{e}"))),
    }
}

