                          done: std::cell::Cell<bool> }
    impl Drop for CallGuard<'_> {
        fn drop(&mut self) { if !self.done.get() {
            let mut kv = vec![("tool", self.name.to_string()),
                              ("reason", "cancelled".to_string()),
                              ("exit_code", "none".to_string()),
                              ("duration_ms", self.start.elapsed().as_millis().to_string())];
            kv.extend(trace_kv(self.trace, self.session));
            crate::audit::write_event(self.app, crate::audit::AuditLevel::Warn, "tool.return", &kv);
