fn anthropic_budget_cap(model_lower: &str) -> u32 {
    // 模型名按 `-` 切段后精确匹配；未知段统一走保守默认，避免
    // "opus-4" 这种子串匹配吞掉未来型号。
    let segs: Vec<&str> = model_lower.split(['-', '.']).collect();
    if segs.windows(2).any(|w| w == ["sonnet", "4"] && segs.get(2) == Some(&"5")) {
        64_000
    } else if segs.windows(2).any(|w| w == ["3", "7"] && segs.get(2) == Some(&"sonnet")) {
        128_000
    } else if segs.iter().any(|s| *s == "opus") && segs.iter().any(|s| s.starts_with("4")) {
        32_000
    } else {
        8_192
    }
}

