/// 配置变更后触发连接重载：保留 JoinHandle 以便关停时观察/取消，
/// 失败走审计，不回滚配置（连接态不是配置的真相源）。
fn trigger_reload(app: &AppHandle) {
    let app = app.clone();
    let handle = tauri::async_runtime::spawn(async move {
        if let Err(e) = shared().reload_from_config(&app).await {
            crate::audit::write_event(
                &app,
                crate::audit::AuditLevel::Warn,
                "mcp.reload_failed",
                &[("err", e.to_string())],
            );
        }
    });
    // 持有 handle，关停路径上可 abort + await，防止重载半截
    HANDLE.with(|h| h.set(Some(handle)));
}

