pub fn anthropic_messages_url(base_url: &str) -> String {
    let trimmed = base_url.trim();
    if trimmed.is_empty() {
        return String::new();
    }
    let mut b = trimmed.trim_end_matches('/').to_string();
    loop {
        let stripped = b
            .strip_suffix("/v1/messages")
            .or_else(|| b.strip_suffix("/messages"))
            .map(str::to_string);
        match stripped {
            Some(s) if s != b => b = s,
            _ => break,
        }
    }
    if b.ends_with("/v1") {
        format!("{b}/messages")
    } else {
        format!("{b}/v1/messages")
    }
}

