pub(crate) fn strip_verbatim(p: PathBuf) -> PathBuf {
    // 用 OsStr 切片避免非 UTF-8 路径 round-trip 损坏
    let s = p.as_os_str();
    let verbatim: &std::ffi::OsStr = if cfg!(windows) {
        r"\\?\".as_ref() // Windows OsStr prefix bytes
    } else {
        "".as_ref()
    };
    if !verbatim.is_empty() {
        if let Some(rest) = strip_os_str_prefix(s, verbatim) {
            // ...UNC\ 形式保守保留
            if !rest.to_string_lossy().starts_with(r"UNC\") {
                return PathBuf::from(rest);
            }
        }
    }
    p
}

