/// 日志轮转：超过 size_limit 字节就改名 .old（旧 .old 覆盖）
/// 注意：调用方必须在持有与日志写入端共享的锁时调用此函数，否则 rename 走之后
/// 已打开的 append handle 仍然写入被重命名的 inode，产生 ghost log。
pub fn rotate_log_if_large(path: &std::path::Path, size_limit: u64) {
    if let Ok(md) = std::fs::metadata(path) {
        if md.len() > size_limit {
            let old = path.with_extension("log.old");
            // Windows 上 rename 不会覆盖已存在 .log.old；先删后 rename
            let _ = std::fs::remove_file(&old);
            if let Err(e) = std::fs::rename(path, &old) {
                eprintln!("log rotate failed: {e}");
            }
        }
    }
}

