fn escape_json_str_inner(v: &str) -> String {
    // `&str` is always valid UTF-8; `serde_json::to_string` cannot fail on
    // it. Use `expect` to surface a programming error rather than silently
    // emitting an empty string into the args JSON.
    let s = serde_json::to_string(v)
        .expect("serializing a valid UTF-8 string into JSON cannot fail");
    // 去掉首尾包围引号，只留转义后的内容
    s.strip_prefix('"')
        .and_then(|x| x.strip_suffix('"'))
        .unwrap_or(&s)
        .to_string()
}

