/// 保留清理：只留最近 keep_runs 个 distinct run（按 (workflow_id, run_started_at) 复合键）
pub fn wa_prune(conn: &rusqlite::Connection, keep_runs: u32) -> Result<usize, String> {
    if keep_runs == 0 {
        return conn.execute("DELETE FROM workflow_audit", []).map_err(|e| e.to_string());
    }
    let n = conn.execute(
        "DELETE FROM workflow_audit WHERE rowid IN (
             SELECT rowid FROM workflow_audit
             WHERE (workflow_id, run_started_at) NOT IN (
                 SELECT workflow_id, run_started_at FROM workflow_audit
                 GROUP BY workflow_id, run_started_at
                 ORDER BY MAX(created_at) DESC LIMIT ?1
             )
         )",
        [keep_runs],
    ).map_err(|e| e.to_string())?;
    Ok(n)
}

