fn is_macos_app_bundle_dir(dir: &std::path::Path) -> bool {
    // 不依赖 to_string_lossy / 精确大小写比对：APFS 大小写不敏感，bundle 名可以是
    // Foo.APP / 旧版 Foo.app，非 UTF-8 路径也要正确识别。
    fn ends_with_app(s: &std::ffi::OsStr) -> bool {
        let bytes = s.as_encoded_bytes();
        bytes.len() >= 4
            && bytes[bytes.len() - 4..].eq_ignore_ascii_case(b".app")
    }
    let mut comps = dir.components().rev();
    matches!(comps.next(), Some(c) if c.as_os_str() == "MacOS")
        && matches!(comps.next(), Some(c) if c.as_os_str() == "Contents")
        && comps.next().is_some_and(|c| ends_with_app(c.as_os_str()))
}

