/// System prompt 槽位枚举。拼接顺序由 `priority()` 显式控制,
/// 增删/重排变体不会改变既有调用点的输出。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PromptSlot {
    /// 静态 SYSTEM_PROMPT（常驻首段）
    Base,
    /// gen_dir_rule（生成目录规则）
    GenDir,
    /// build_skill_block（已安装技能清单的「名称+描述」层,progressive disclosure 第一层）
    SkillCatalog,
    /// interactive 模式技能的正文（fall-through 给 LLM 的具体内容）
    SkillBody,
    /// recovery_hint（auto-mode 失败兜底,LLM 决策下一步的依据）
    Recovery,
    /// plan_block（动态计划步骤,PREVR 第二层）
    Plan,
}

impl PromptSlot {
    /// 显式拼接优先级,枚举重排不影响输出。
    pub fn priority(self) -> u8 {
        match self {
            PromptSlot::Base => 0,
            PromptSlot::GenDir => 1,
            PromptSlot::SkillCatalog => 2,
            PromptSlot::SkillBody => 3,
            PromptSlot::Recovery => 4,
            PromptSlot::Plan => 5,
        }
    }
}

