pub fn kill_tree(child: &mut Child, limits: &RunLimits) {
    limits.terminate();
    #[cfg(unix)]
    {
        let pid_u32 = child.id();
        if pid_u32 <= i32::MAX as u32 {
            let pid = pid_u32 as i32;
            let _ = silent_cmd("kill").args(["-9", &format!("-{pid}")]).status();
        }
    }
    #[cfg(windows)]
    {
        let pid = child.id().to_string();
        let _ = silent_cmd("taskkill")
            .args(["/PID", &pid, "/T", "/F"])
            .status();
    }
    let _ = child.kill();
    let _ = child.wait();
}

