// Reset transient test state on URL/format change, AND bump a token so any
  // in-flight runTest() whose resolve arrives late can be detected as stale.
  const testTokenRef = useRef(0);
  useEffect(() => {
    setTestState("idle");
    setTestMsg("");
    testTokenRef.current += 1;
  }, [model.baseUrl, apiProvider]);

  const runTest = async () => {
    if (testState === "testing" || vendorDisabled) return;
    const myToken = testTokenRef.current;
    setTestState("testing");
    setTestMsg("");
    try {
      const r = await invoke<{ ok: boolean; status?: number; error?: string }>(
        "bot_test_connection",
        { baseUrl: model.baseUrl, apiFormat: apiProvider, vendor: model.vendor ?? null },
      );
      if (myToken !== testTokenRef.current) return; // URL/format changed mid-flight; discard
      if (r.ok) { setTestState("ok"); setTestMsg(r.status ? `连接成功（HTTP ${r.status}）` : "连接成功"); }
      else { setTestState("fail"); setTestMsg(r.error ?? (r.status ? `HTTP ${r.status}` : "连接失败")); }
    } catch (e) {
      if (myToken !== testTokenRef.current) return;
      setTestState("fail");
      setTestMsg(formatCommandError(e));
    }
    if (myToken === testTokenRef.current) onTested?.();
  };

