function parseKeyValueLines(
  text: string,
  sep: string,
  onError?: (line: string, reason: string) => void
): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of text.split("\n")) {
    const t = line.trim();
    if (!t) continue;
    const i = t.indexOf(sep);
    if (i < 0) {
      onError?.(t, "missing separator");
      continue;
    }
    const key = t.slice(0, i).trim();
    if (!key) { onError?.(t, "empty key"); continue; }
    if (key in out) { onError?.(t, "duplicate key"); continue; }
    out[key] = t.slice(i + 1).trim();
  }
  return out;
}

