function nodeBorder(
  task: Task | undefined,
  liveStatus?: TaskNodeData["liveStatus"],
): string {
  if (liveStatus === "running") return "ring-2 ring-[var(--info,#3b82f6)] animate-pulse";
  if (liveStatus === "failed") return "ring-2 ring-[var(--danger,#ef4444)]";
  if (liveStatus === "skipped") return "ring-2 ring-[var(--edge)] opacity-70";
  if (liveStatus === "done") return "ring-2 ring-[var(--ok,#22c55e)]";
  if (task?.result?.status !== undefined && task.result.status !== "success")
    return "ring-2 ring-[var(--danger,#ef4444)]";
  if (task?.column === "doing" && task.botAssigned)
    return "ring-2 ring-[var(--info,#3b82f6)]";
  if (task?.column !== "done") return "";

